"""The Fabric notebooks are generated files. These tests keep them in step with their sources
and make sure the code inside them runs without the simulator package."""
import importlib.util
import json
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]
NOTEBOOKS = ROOT / "fabric" / "notebooks"
NAMES = ["01_load_reference_data", "02_generate_history", "03_refresh_forecast", "04_question_bank"]

pd = pytest.importorskip("pandas")


def cells(name, kind="code"):
    notebook = json.loads((NOTEBOOKS / f"{name}.ipynb").read_text(encoding="utf-8"))
    return ["".join(c["source"]) for c in notebook["cells"] if c["cell_type"] == kind]


def question_bank():
    spec = importlib.util.spec_from_file_location("question_bank", ROOT / "tools" / "question_bank.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def test_generated_files_match_their_sources():
    result = subprocess.run([sys.executable, str(ROOT / "tools" / "build-notebooks.py"), "--check"],
                            capture_output=True, text=True)
    assert result.returncode == 0, result.stderr


@pytest.mark.parametrize("name", NAMES)
def test_every_code_cell_compiles(name):
    for number, source in enumerate(cells(name)):
        compile(source, f"{name}[{number}]", "exec")


def test_library_cell_runs_without_the_package():
    """The copy of catalog, climate and history inside notebook 02 must work on its own."""
    library = next(c for c in cells("02_generate_history") if c.startswith("# Generated by tools/build-notebooks.py"))
    assert "from ." not in library and "import windfarm_sim" not in library
    namespace = {"__name__": "notebook"}
    exec(compile(library, "library-cell", "exec"), namespace)
    site = json.loads((ROOT / "data" / "reference" / "site.json").read_text(encoding="utf-8"))
    tables = namespace["generate"](site, as_of="2026-03-01T00:00:00+00:00", start="2026-01-01T00:00:00+00:00")
    assert len(tables["scada_10min"]) == 59 * 144 * 12
    forecast = namespace["forecast_table"](site, start="2026-02-25T00:00:00+00:00", as_of="2026-03-01T00:00:00+00:00")
    assert set(forecast["ForecastType"]) == {"Day-ahead", "Latest"}
    # Notebook 03 carries the same copy.
    assert library in cells("03_refresh_forecast")


def test_history_notebook_writes_every_table_the_questions_use():
    bank = question_bank()
    site = json.loads((ROOT / "data" / "reference" / "site.json").read_text(encoding="utf-8"))
    from windfarm_sim import history
    tables = history.generate(site, as_of="2026-03-01T00:00:00+00:00", start="2026-01-01T00:00:00+00:00")
    known = {f"ops_{name}" for name in tables}
    known |= {line.split('"')[3] for line in cells("01_load_reference_data")[1].splitlines() if '.csv": ("' in line}
    known |= {"ref_gis_features", "ref_terrain_grid", "ref_sop_documents"}
    for question in bank.QUESTIONS:
        for table in question["tables"].split(", "):
            assert table in known, f"{question['id']} uses {table}"
            assert table in question["sql"], f"{question['id']} lists {table} but does not query it"


def test_question_ids_are_unique_and_grouped():
    bank = question_bank()
    ids = [q["id"] for q in bank.QUESTIONS + bank.LIVE_QUESTIONS]
    assert len(ids) == len(set(ids))
    assert {i[:2] for i in ids} <= set(bank.PERSONAS)
    assert len(bank.QUESTIONS) >= 35
